?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moderação — Arena</title><link rel="stylesheet" href="assets/app.css"></head><body class="adminskin"><aside class="side"><a class="side-logo">ARENA DE <b>AÇO</b><small>ADMINISTRAÇÃO</small></a><a href="admin.php">⌂ Dashboard</a><a class="active" href="admin_chat.php">◉ Comunidade</a><a href="admin_document.php">▣ PDFs exclusivos</a><a href="admin_tickets.php">♧ Suporte</a><a class="exit" href="logout.php">Sair</a></aside><main class="adminmain"><header class="adminhead"><div><h1>Moderação da comunidade</h1><span>Remova mensagens impróprias sem apagar o histórico.</span></div></header><?php if($ok):?><p class="alert ok"><?=e($ok)?></p><?php endif?><section class="panel"><div class="table user-table"><div class="tr th"><span>Autor</span><span>Mensagem</span><span>Data</span><span>Status</span><span>Ação</span></div><?php foreach($messages as $m):?><div class="tr"><span><?=e($m['name'])?><small><?=e($m['email'])?></small></span><span><?=e($m['message'])?></span><span><?=date('d/m/Y H:i',strtotime($m['created_at']))?></span><span><b class="status <?=e($m['status'])?>"><?=e($m['status'])?></b></span><span><form method="post"><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="<?=$m['status']==='hidden'?'show':'hide'?>"><button class="outline" type="submit"><?=$m['status']==='hidden'?'Mostrar':'Ocultar'?></button></form></span></div><?php endforeach;if(!$messages):?><p class="muted">Ainda não há mensagens.</p><?php endif?></div></section></main></body></html>
